parameters.text:
=Topic: {{ $json.topic }}

Content brief: {{ $json.brief }}

Research findings (JSON):
{{ JSON.stringify($json.findings, null, 2) }}

Known gaps in the research:
{{ JSON.stringify($json.gaps) }}

Previous draft (empty if this is the first draft):
{{ $json.previous_draft }}

Revision notes from the reviewer (empty on first draft):
{{ $json.revision_notes }}

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "draft": {
      "type": "string",
      "description": "The full draft in markdown with inline [n] citations. Empty string if blocked."
    },
    "sources_used": {
      "type": "array",
      "description": "URLs cited in the draft, in citation order. Only URLs from the provided findings.",
      "items": { "type": "string" }
    },
    "blocked_reason": {
      "type": "string",
      "description": "Empty string if a draft was written. Otherwise, why the findings cannot support the brief."
    },
    "changes_made": {
      "type": "string",
      "description": "A one or two sentence summary of what changed from the previous draft in response to revision_notes. Empty string if this is the first draft."
    }
  },
  "required": ["draft", "sources_used", "blocked_reason", "changes_made"]
}
